"use client";
import {useState} from 'react';
import {PremiumTabs} from './PremiumTabs';
import './TabBatchC.css';

/* ---------- 1. Kanban project (Cadence) ---------- */
type Task={id:string;title:string;tag:string;who:string;due:string;col:number;prio:number;start:number;len:number};
const kbInit:Task[]=[
 {id:'KB-101',title:'Empty state for the mobile board',tag:'Design',who:'AK',due:'Thu',col:0,prio:2,start:0,len:2},
 {id:'KB-102',title:'Sprint summary email copy',tag:'Content',who:'RS',due:'Fri',col:0,prio:1,start:1,len:2},
 {id:'KB-103',title:'Drag preview flickers on scroll',tag:'Bug',who:'JL',due:'Today',col:1,prio:3,start:0,len:3},
 {id:'KB-104',title:'Column virtualization pass',tag:'Perf',who:'JL',due:'Wed',col:1,prio:2,start:2,len:3},
 {id:'KB-105',title:'Keyboard move between columns',tag:'Access',who:'AK',due:'Mon',col:2,prio:1,start:0,len:2},
 {id:'KB-106',title:'Archive sprint 11 cards',tag:'Chore',who:'RS',due:'Done',col:2,prio:0,start:3,len:2},
];
const kbCols=['To do','In progress','Done'];
const kbDays=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
const prioWord=['Low','Medium','High','Urgent'];
export function KanbanStudy(){
 const[tasks,setTasks]=useState(kbInit);
 const[mine,setMine]=useState(false);
 const[sel,setSel]=useState('KB-103');
 const[n,setN]=useState(0);
 const move=(id:string)=>setTasks(ts=>ts.map(t=>t.id===id?{...t,col:(t.col+1)%3}:t));
 const add=(ci:number)=>{setN(x=>x+1);setTasks(ts=>[...ts,{id:`KB-${107+n}`,title:'Untitled task',tag:'Design',who:'JL',due:'—',col:ci,prio:0,start:4,len:1}]);};
 const vis=(t:Task)=>!mine||t.who==='JL';
 const card=(t:Task)=><article className="kb-card" key={t.id}><i className="kb-tag" data-t={t.tag}>{t.tag}</i><p>{t.title}</p><footer><span className="tbc-av" data-p={t.who}>{t.who}</span><time>{t.due}</time><button aria-label={`Move ${t.id} to ${kbCols[(t.col+1)%3]}`} onClick={()=>move(t.id)}>→</button></footer></article>;
 const board=<div className="kb-board">{kbCols.map((c,ci)=><section className="kb-col" key={c} aria-label={`${c} column`}><div className="kb-col-head"><b>{c}</b><span>{tasks.filter(t=>t.col===ci).length}</span></div>{tasks.filter(t=>t.col===ci&&vis(t)).map(card)}<button className="kb-add" onClick={()=>add(ci)}>＋ New card</button></section>)}</div>;
 const list=<div className="kb-list" role="table" aria-label="Sprint tasks"><div className="kb-row kb-row-head" role="row"><span>Key</span><span>Task</span><span>Status</span><span>Priority</span><span>Owner</span><span>Due</span></div>{tasks.filter(vis).map(t=><div className="kb-row" role="row" key={t.id}><span className="kb-id">{t.id}</span><span className="kb-title">{t.title}</span><button className="kb-status" data-c={t.col} onClick={()=>move(t.id)} aria-label={`Status ${kbCols[t.col]}. Activate to move to ${kbCols[(t.col+1)%3]}`}>{kbCols[t.col]}</button><span className="kb-prio" role="img" aria-label={`${prioWord[t.prio]} priority`}>{[0,1,2].map(d=><i key={d} data-on={d<t.prio}/>)}</span><span className="tbc-av" data-p={t.who}>{t.who}</span><time>{t.due}</time></div>)}</div>;
 const picked=tasks.find(t=>t.id===sel);
 const timeline=<div className="kb-gantt"><div className="kb-gantt-days">{kbDays.map(d=><span key={d}>{d}</span>)}</div><div className="kb-gantt-body"><i className="kb-today" style={{left:'38%'}}><b>Today</b></i>{tasks.filter(vis).map(t=><button key={t.id} className="kb-bar" data-c={t.col} data-sel={sel===t.id} style={{left:`${t.start/7*100}%`,width:`${t.len/7*100}%`}} onClick={()=>setSel(t.id)} aria-pressed={sel===t.id}><span>{t.id}</span>{t.title}</button>)}</div>{picked&&<p className="kb-gantt-detail"><b>{picked.id}</b> {picked.title} · Owner {picked.who} · {kbDays[picked.start]}–{kbDays[Math.min(6,picked.start+picked.len-1)]}</p>}</div>;
 return <section className="tbc-study tbc-kanban" aria-label="Kanban project tabs study">
  <div className="kb-top"><b className="kb-logo"><svg width="15" height="15" viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.6" fill="none" stroke="#4772bd" strokeWidth="2.2"/><path d="M8 1.4 A6.6 6.6 0 0 1 14.6 8 L8 8 Z" fill="#4772bd"/></svg>Cadence</b><span className="kb-search">⌕ Search tasks</span><span className="tbc-av" data-p="JL">JL</span></div>
  <div className="kb-head"><div><h2>Mobile board <span>Sprint 12</span></h2><p>Nov 16 – Nov 27 · 6 tasks · 3 people</p></div><button className="kb-filter" aria-pressed={mine} onClick={()=>setMine(v=>!v)}>{mine?'✓ Assigned to me':'Assigned to me'}</button></div>
  <PremiumTabs label="Sprint views" items={[{id:'board',label:'Board',content:board},{id:'list',label:'List',content:list},{id:'timeline',label:'Timeline',content:timeline}]}/>
 </section>;
}

/* ---------- 2. Analytics (Lantern) ---------- */
const anRanges=['7 days','30 days','90 days'];
const anData=[
 {visitors:'8,214',views:'19,402',bounce:'41%',avg:'2m 18s',d:['+12%','+9%','−3%','+6%'],bars:[34,41,38,52,47,61,58,72,66,78,84,92],ev:[['signup_click',412],['doc_open',388],['share_invite',301],['search_run',264],['theme_toggle',149]],fun:[['Visited site',8214],['Viewed pricing',2310],['Started trial',486],['Subscribed',121]]},
 {visitors:'31,908',views:'78,114',bounce:'44%',avg:'2m 04s',d:['+6%','+4%','+1%','−2%'],bars:[22,28,26,35,31,44,40,52,48,57,63,71],ev:[['signup_click',1718],['doc_open',1502],['search_run',1188],['share_invite',1104],['theme_toggle',642]],fun:[['Visited site',31908],['Viewed pricing',8806],['Started trial',1893],['Subscribed',402]]},
 {visitors:'96,431',views:'241,775',bounce:'39%',avg:'2m 31s',d:['+18%','+15%','−6%','+11%'],bars:[18,22,27,25,33,38,36,44,49,58,64,77],ev:[['signup_click',5204],['doc_open',4781],['search_run',3902],['share_invite',3410],['theme_toggle',1877]],fun:[['Visited site',96431],['Viewed pricing',27119],['Started trial',6084],['Subscribed',1341]]},
];
const fmt=(n:number)=>n.toLocaleString('en-US');
export function AnalyticsStudy(){
 const[range,setRange]=useState(0);
 const[site,setSite]=useState(0);
 const[bar,setBar]=useState(11);
 const[sort,setSort]=useState(0);
 const[step,setStep]=useState(1);
 const d=anData[range];
 const kpis=[['Visitors',d.visitors],['Pageviews',d.views],['Bounce rate',d.bounce],['Avg. visit',d.avg]];
 const maxBar=Math.max(...d.bars);
 const evs=[...d.ev].sort((a,b)=>sort?(a[0] as string).localeCompare(b[0] as string):(b[1] as number)-(a[1] as number));
 const maxEv=d.ev[0][1] as number;
 const visitors=<div className="an-chart"><div className="an-bars" role="group" aria-label={`Monthly visitor bar chart, peak ${fmt(maxBar*107)} visitors`}>{d.bars.map((h,i)=><button key={i} className="an-bar" data-on={bar===i} style={{height:`${h/maxBar*100}%`}} onClick={()=>setBar(i)} aria-label={`${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][i]}: ${fmt(h*107)} visitors`}/>)}</div><div className="an-x">{['J','F','M','A','M','J','J','A','S','O','N','D'].map((m,i)=><span key={i}>{m}</span>)}</div><p className="an-read"><b>{fmt(d.bars[bar]*107)}</b> visitors in {['January','February','March','April','May','June','July','August','September','October','November','December'][bar]}</p></div>;
 const events=<div className="an-events"><button className="an-sort" onClick={()=>setSort(v=>v?0:1)}>Sort: {sort?'name':'count'} ⇅</button>{evs.map(([name,count])=><div className="an-ev" key={name as string}><span className="an-ev-name">{(name as string).replace('_',' ')}</span><span className="an-ev-track"><i style={{width:`${(count as number)/maxEv*100}%`}}/></span><b>{fmt(count as number)}</b></div>)}</div>;
 const fun=<div className="an-funnel">{d.fun.map(([label,v],i)=>{const pct=Math.round((v as number)/(d.fun[0][1] as number)*100);const prev=i?Math.round((v as number)/(d.fun[i-1][1] as number)*100):100;return <button className="an-step" data-on={step===i} key={label as string} onClick={()=>setStep(i)} aria-pressed={step===i}><span className="an-step-fill" style={{width:`${pct}%`}}/><span className="an-step-row"><b>{label}</b><span>{fmt(v as number)} · {i?`${prev}% of previous`:'100%'}</span></span></button>;})}</div>;
 return <section className="tbc-study tbc-analytics" aria-label="Analytics dashboard tabs study">
  <div className="an-top"><b className="an-logo"><svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.8" fill="none" stroke="#31599f" strokeWidth="2"/><path d="M8 8 L8 1.2 A6.8 6.8 0 0 1 14.8 8 Z" fill="#d4713a"/></svg>Lantern</b><button className="an-site" onClick={()=>setSite(v=>v?0:1)}>{['northstudio.shop','fableandfirn.com'][site]} ⌄</button><div className="an-ranges" role="group" aria-label="Date range">{anRanges.map((r,i)=><button key={r} aria-pressed={range===i} onClick={()=>setRange(i)}>{r}</button>)}</div></div>
  <div className="an-kpis">{kpis.map(([k,v],i)=><div className="an-kpi" key={k}><span>{k}</span><b>{v}</b><i data-up={!d.d[i].startsWith('−')}>{d.d[i]}</i></div>)}</div>
  <div className="an-card"><PremiumTabs label="Analytics reports" items={[{id:'visitors',label:'Visitors',content:visitors},{id:'events',label:'Events',content:events},{id:'conversions',label:'Conversions',content:fun}]}/></div>
 </section>;
}

/* ---------- 3. Learning app (Chapterhouse) ---------- */
const lnQs=[{q:'Which of these is a serif typeface?',opts:['Inter','Georgia','Futura','Space Grotesk'],a:1,why:'Georgia has small finishing strokes at the ends of its letterforms. That is what makes it a serif.'},{q:'What does tracking adjust?',opts:['Line height','Space between letters','Font weight','Paragraph width'],a:1,why:'Tracking is the uniform spacing applied across a range of letters.'}];
export function LearningStudy(){
 const[done,setDone]=useState(42);
 const[pick,setPick]=useState(-1);
 const[checked,setChecked]=useState(false);
 const[notes,setNotes]=useState('Serif = finishing strokes.\nTracking = letter spacing across a word.');
 const[saved,setSaved]=useState(true);
 const[pq,setPq]=useState(0);
 const Q=lnQs[pq];
 const lesson=<div className="ln-lesson"><span className="ln-kicker">Chapter 4 · Typography basics</span><h3>Reading letterforms</h3><p>Every typeface has a posture. Before you compare details, stand back and notice whether the letters feel constructed or written, warm or cool, old or new.</p><div className="ln-figure" role="img" aria-label="Large lowercase letter a set in a serif face"><span>a</span><div><b>serif</b><i style={{width:'64%'}}/><small>small stroke at the end of a stem</small></div><div><b>counter</b><i style={{width:'38%'}}/><small>enclosed space inside the letter</small></div></div><p>Serif faces carry small finishing strokes; sans serifs end cleanly. Neither is better. They simply speak in different tones.</p><button className="ln-finish" onClick={()=>setDone(d=>Math.min(100,d+14))}>{done>=100?'Chapter finished ✓':'Mark section read'}</button></div>;
 const exercise=<div className="ln-ex"><span className="ln-kicker">Exercise {pq+1} of {lnQs.length}</span><h3>{Q.q}</h3>{Q.opts.map((o,i)=><button key={o} className="ln-opt" data-pick={pick===i} data-right={checked&&i===Q.a} data-wrong={checked&&pick===i&&i!==Q.a} onClick={()=>{if(!checked)setPick(i);}}><i>{String.fromCharCode(65+i)}</i>{o}</button>)}<div className="ln-ex-foot">{checked?<p className="ln-why" role="status">{pick===Q.a?'Correct. ':'Not quite. '}{Q.why}</p>:<span/>}<div>{checked?<button className="ln-check" onClick={()=>{setChecked(false);setPick(-1);setPq(x=>(x+1)%lnQs.length);}}>Next question →</button>:<button className="ln-check" disabled={pick<0} onClick={()=>setChecked(true)}>Check answer</button>}</div></div></div>;
 const notesP=<div className="ln-notes"><span className="ln-kicker">Your margin notes</span><textarea aria-label="Chapter notes" value={notes} onChange={e=>{setNotes(e.target.value);setSaved(false);}} rows={7}/><div className="ln-notes-foot"><span aria-live="polite">{saved?'Saved just now':'Unsaved changes'}</span><button className="ln-check" disabled={saved} onClick={()=>setSaved(true)}>Save notes</button></div></div>;
 return <section className="tbc-study tbc-learning" aria-label="Learning app tabs study">
  <div className="ln-top"><b className="ln-logo"><svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 0.8 L10 6 L15.2 8 L10 10 L8 15.2 L6 10 L0.8 8 L6 6 Z" fill="#8a5a24"/></svg>Chapterhouse</b><div className="ln-progress"><span>{done}%</span><div><i style={{width:`${done}%`}}/></div></div><span className="tbc-av" data-p="MT">MT</span></div>
  <div className="ln-body">
   <PremiumTabs label="Course sections" orientation="vertical" items={[{id:'lesson',label:'Lesson',content:lesson},{id:'exercise',label:'Exercise',content:exercise},{id:'notes',label:'Notes',content:notesP}]}/>
  </div>
 </section>;
}

/* ---------- 4. Issue detail (Depot) ---------- */
const isCommits=[{h:'a41f9c2',m:'Focus the first field after cart re-render',w:'JL',t:'2h ago',f:['+18 −6  CartDrawer.tsx','+4 −1  useCart.ts']},{h:'7b03e8d',m:'Restore focus ring on quantity stepper',w:'AK',t:'5h ago',f:['+9 −2  Stepper.tsx']},{h:'e5c1a77',m:'Add regression test for checkout focus order',w:'JL',t:'1d ago',f:['+31 −0  checkout.focus.test.tsx']}];
const isChecksInit=[{n:'build (18.x)',s:'pass',t:'1m 42s'},{n:'lint + typecheck',s:'pass',t:'58s'},{n:'test: checkout flows',s:'fail',t:'3m 10s'},{n:'visual regression',s:'run',t:'queued'}];
export function IssueStudy(){
 const[comments,setComments]=useState([{w:'AK',t:'Yesterday',b:'Reproduced on Safari 19 and Chrome 142. Focus lands on body right after the cart drawer re-renders. Traced it to the key change on the line items list.'},{w:'JL',t:'2 hours ago',b:'Good catch. The remount wipes activeElement. I will restore focus to the checkout button after the cart commits, and add a regression test so it stays fixed.'}]);
 const[draft,setDraft]=useState('');
 const[liked,setLiked]=useState(3);
 const[openC,setOpenC]=useState(0);
 const[checks,setChecks]=useState(isChecksInit);
 const[busy,setBusy]=useState(false);
 const rerun=()=>{if(busy)return;setBusy(true);setChecks(cs=>cs.map(c=>({...c,s:'run',t:'running'})));setTimeout(()=>{setChecks(cs=>cs.map(c=>({...c,s:'pass',t:c.t==='queued'?'44s':c.t==='running'?'1m 05s':c.t})));setBusy(false);},2400);};
 const post=()=>{const v=draft.trim();if(!v)return;setComments(cs=>[...cs,{w:'JL',t:'Just now',b:v}]);setDraft('');};
 const convo=<div className="is-convo">{comments.map((c,i)=><article className="is-comment" key={i}><span className="tbc-av" data-p={c.w}>{c.w}</span><div className="is-bubble"><header><b>{c.w==='JL'?'jamiel':c.w==='AK'?'aaravk':'mira'}</b><time>{c.t}</time>{i===0&&<button className="is-react" aria-pressed={liked>3} onClick={()=>setLiked(v=>v>3?3:4)}>👍 {liked}</button>}</header><p>{c.b}</p></div></article>)}<div className="is-composer"><span className="tbc-av" data-p="JL">JL</span><div className="is-box"><textarea aria-label="Write a comment" placeholder="Leave a comment" value={draft} onChange={e=>setDraft(e.target.value)} rows={3}/><div><span>Markdown supported</span><button className="is-post" disabled={!draft.trim()} onClick={post}>Comment</button></div></div></div></div>;
 const commits=<div className="is-commits">{isCommits.map((c,i)=><div className="is-commit" key={c.h}><button className="is-commit-row" aria-expanded={openC===i} onClick={()=>setOpenC(openC===i?-1:i)}><code>{c.h}</code><span>{c.m}</span><time>{c.w} · {c.t}</time></button>{openC===i&&<div className="is-diff">{c.f.map(f=><p key={f}>{f}</p>)}</div>}</div>)}</div>;
 const checksP=<div className="is-checks"><div className="is-checks-head"><span>{checks.every(c=>c.s==='pass')?'All checks passing':'Some checks still running'}</span><button className="is-rerun" disabled={busy} onClick={rerun}>{busy?'Running…':'Re-run all'}</button></div>{checks.map(c=><div className="is-check" key={c.n}><i className={`is-dot is-${c.s}`}/><b>{c.n}</b><time>{c.t}</time></div>)}</div>;
 return <section className="tbc-study tbc-issue" aria-label="Issue detail tabs study">
  <div className="is-top"><b className="is-logo"><svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><circle cx="4.5" cy="3.5" r="2.3" fill="#23272f"/><circle cx="4.5" cy="12.5" r="2.3" fill="#23272f"/><circle cx="11.8" cy="8" r="2.3" fill="none" stroke="#23272f" strokeWidth="1.8"/><path d="M4.5 5.8 V10.2 M4.5 5.8 C4.5 8 6.5 8 9.5 8" fill="none" stroke="#23272f" strokeWidth="1.8"/></svg>Depot</b><span>north / storefront</span><span className="is-crumb">Issues</span></div>
  <div className="is-head"><h2>Checkout button loses focus after cart update <span>#482</span></h2><p><i className="is-open">● Open</i> jamiel opened this issue 2 days ago · {comments.length} comments</p></div>
  <PremiumTabs label="Issue sections" items={[{id:'conversation',label:'Conversation',badge:String(comments.length),content:convo},{id:'commits',label:'Commits',badge:'3',content:commits},{id:'checks',label:'Checks',badge:String(checks.length),content:checksP}]}/>
 </section>;
}

/* ---------- 5. Delivery tracking (Bluecrate) ---------- */
const dvSteps=[['Parcel collected','Tue 09:12','Bengaluru hub'],['In transit','Tue 21:40','Left on route truck 14'],['Arrived locally','Wed 07:05','Mysuru depot'],['Out for delivery','Today 10:24','With courier · 4 stops away'],['Delivered','','By 7:00 pm today']];
const dvItems=[['Linen throw · Rust','Qty 1 · 1.2 kg','₹2,450'],['Ceramic pour-over set','Qty 1 · 0.8 kg','₹1,890'],['Cotton napkins, set of 4','Qty 2 · 0.3 kg','₹640']];
export function DeliveryStudy(){
 const[copied,setCopied]=useState(false);
 const[msg,setMsg]=useState([['them','Hi! Your parcel is 4 stops away. The courier will call on arrival.']]);
 const[draft,setDraft]=useState('');
 const[rate,setRate]=useState(0);
 const copy=()=>{try{navigator.clipboard?.writeText('BX-2481-0097');}catch(e){}setCopied(true);setTimeout(()=>setCopied(false),1600);};
 const send=()=>{const v=draft.trim();if(!v)return;setMsg(m=>[...m,['me',v]]);setDraft('');setTimeout(()=>setMsg(m=>[...m,['them','Got it - updating the courier note now.']]),1200);};
 const status=<div className="dv-status"><div className="dv-route"><svg viewBox="0 0 320 90" role="img" aria-label="Route from Bengaluru to Mysuru, parcel near destination"><path d="M14 66 C 80 10, 130 84, 196 40 S 286 30, 306 58" fill="none" strokeWidth="2.5" strokeDasharray="5 6" className="dv-path"/><circle cx="14" cy="66" r="5" className="dv-pin"/><circle cx="306" cy="58" r="6" className="dv-pin dv-end"/><circle r="6" className="dv-van"><animateMotion dur="5s" repeatCount="indefinite" path="M14 66 C 80 10, 130 84, 196 40 S 286 30, 306 58"/></circle></svg><div><span>Bengaluru</span><span>Mysuru</span></div></div><ol className="dv-steps">{dvSteps.map((s,i)=><li key={s[0]} data-done={i<3} data-now={i===3}><i/>{s[0]}<span>{s[2]}</span><time>{s[1]}</time></li>)}</ol></div>;
 const items=<div className="dv-items">{dvItems.map((it,i)=><div className="dv-item" key={it[0]}><span className={`dv-thumb dv-t${i}`} role="img" aria-label={`${it[0]} thumbnail`}/><div><b>{it[0]}</b><small>{it[1]}</small></div><span>{it[2]}</span></div>)}<div className="dv-total"><span>Order total</span><b>₹4,980</b></div><p className="dv-barcode" aria-hidden="true">▌▍▎▏▌▍▎▍▌▎▍▏▌▍▎▍▌▏▎▍▌</p></div>;
 const support=<div className="dv-support"><div className="dv-chat" aria-live="polite">{msg.map((m,i)=><p key={i} className={m[0]==='me'?'dv-me':'dv-them'}>{m[1]}</p>)}</div><div className="dv-rate" role="group" aria-label="Rate the courier">{[1,2,3,4,5].map(n=><button key={n} aria-pressed={rate>=n} aria-label={`${n} star`} onClick={()=>setRate(n)}>{n<=rate?'★':'☆'}</button>)}</div><div className="dv-send"><input aria-label="Message support" placeholder="Write to support…" value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')send();}}/><button className="is-post" disabled={!draft.trim()} onClick={send}>Send</button></div></div>;
 return <section className="tbc-study tbc-delivery" aria-label="Delivery tracking tabs study">
  <div className="dv-top"><b className="dv-logo"><svg width="15" height="15" viewBox="0 0 16 16" aria-hidden="true"><rect x="1.4" y="1.4" width="13.2" height="13.2" rx="2" fill="none" stroke="#1e2126" strokeWidth="1.9"/><path d="M1.4 1.4 L14.6 14.6 M14.6 1.4 L1.4 14.6" stroke="#1e2126" strokeWidth="1.5"/></svg>Bluecrate</b><span>Tracking</span></div>
  <div className="dv-hero"><div><h2>Out for delivery</h2><p>Arriving today by 7:00 pm</p></div><button className="dv-copy" onClick={copy} aria-live="polite">{copied?'Copied ✓':'BX-2481-0097 ⧉'}</button></div>
  <PremiumTabs label="Shipment details" items={[{id:'status',label:'Status',content:status},{id:'items',label:'Items',badge:'3',content:items},{id:'support',label:'Support',content:support}]}/>
 </section>;
}

/* ---------- 6. Onboarding (Juniper) ---------- */
const obColors=['#7a5c3e','#3e6b5a','#45608f','#8a4a52'];
export function OnboardingStudy(){
 const[name,setName]=useState('');
 const[role,setRole]=useState('Designer');
 const[av,setAv]=useState(1);
 const[team,setTeam]=useState([['aarav@north.studio','Editor']]);
 const[em,setEm]=useState('');
 const[ws,setWs]=useState('');
 const[region,setRegion]=useState(0);
 const[finished,setFinished]=useState(false);
 const slug=ws.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'your-team';
 const initials=name.trim()?name.trim().split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase():'?';
 const addMember=()=>{const v=em.trim();if(!v||!v.includes('@'))return;setTeam(t=>[...t,[v,'Viewer']]);setEm('');};
 const personal=<div className="ob-pane"><h3>What should we call you?</h3><label className="ob-field"><span>Display name</span><input value={name} onChange={e=>setName(e.target.value)} placeholder="Mira Thomas"/></label><label className="ob-field"><span>Your role</span><select value={role} onChange={e=>setRole(e.target.value)}><option>Designer</option><option>Engineer</option><option>Producer</option><option>Founder</option></select></label><div className="ob-avs" role="group" aria-label="Avatar colour">{obColors.map((c,i)=><button key={c} className="ob-av" style={{background:c}} aria-pressed={av===i} aria-label={`Colour ${i+1}`} onClick={()=>setAv(i)}>{av===i?initials:''}</button>)}</div></div>;
 const teamP=<div className="ob-pane"><h3>Invite your team</h3><p className="ob-sub">They get an email with a link to join.</p>{team.map((m,i)=><div className="ob-member" key={i}><span className="tbc-av" data-p="AK">{m[0][0].toUpperCase()}</span><b>{m[0]}</b><select value={m[1]} onChange={e=>setTeam(t=>t.map((x,k)=>k===i?[x[0],e.target.value]:x))}><option>Editor</option><option>Viewer</option><option>Admin</option></select><button className="ob-x" aria-label={`Remove ${m[0]}`} onClick={()=>setTeam(t=>t.filter((_,k)=>k!==i))}>×</button></div>)}<div className="ob-invite"><input aria-label="Teammate email" placeholder="teammate@studio.com" value={em} onChange={e=>setEm(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')addMember();}}/><button onClick={addMember} disabled={!em.includes('@')}>＋ Add</button></div></div>;
 const workspace=<div className="ob-pane"><h3>Name your workspace</h3><label className="ob-field"><span>Workspace name</span><input value={ws} onChange={e=>setWs(e.target.value)} placeholder="North Studio"/></label><p className="ob-slug" aria-live="polite">juniper.app/<b>{slug}</b></p><div className="ob-region" role="radiogroup" aria-label="Data region">{['India (Mumbai)','EU (Frankfurt)'].map((r,i)=><button key={r} role="radio" aria-checked={region===i} className="ob-reg" data-on={region===i} onClick={()=>setRegion(i)}><i/>{r}</button>)}</div><button className="ob-finish" onClick={()=>setFinished(true)}>{finished?'Workspace ready ✓':'Finish setup'}</button>{finished&&<p className="ob-done" role="status">Everything is set up for <b>{ws||'your team'}</b>. This demo stops here - nothing was created.</p>}</div>;
 return <section className="tbc-study tbc-onboard" aria-label="Onboarding flow tabs study">
