import "./PremiumTabs.css";
import { useState, useEffect, useId, useLayoutEffect, useRef } from "react";
function PremiumTabs({ items, label, variant = 0, value, defaultValue, onValueChange, orientation = 'horizontal', activation = 'automatic' }) {
    const first = items.find(i => !i.disabled)?.id ?? '';
    const [internal, setInternal] = useState(defaultValue ?? first);
    const requested = value ?? internal;
    const current = items.some(i => i.id === requested && !i.disabled) ? requested : first;
    const [focusId, setFocusId] = useState(current);
    const uid = useId();
    const root = useRef(null), list = useRef(null), buttons = useRef([]);
    const vertical = orientation === 'vertical';
    const select = (id) => { setFocusId(id); if (value === undefined)
        setInternal(id); onValueChange?.(id); };
    const measure = () => { const i = items.findIndex(t => t.id === current), el = buttons.current[i], r = root.current; if (el && r && el.offsetWidth > 0) {
        r.style.setProperty('--tab-x', `${el.offsetLeft}px`);
        r.style.setProperty('--tab-y', `${el.offsetTop}px`);
        r.style.setProperty('--tab-w', `${el.offsetWidth}px`);
        r.style.setProperty('--tab-h', `${el.offsetHeight}px`);
    } };
    useLayoutEffect(() => { measure(); const ob = new ResizeObserver(measure); if (list.current)
        ob.observe(list.current); buttons.current.forEach(b => { if (b)
        ob.observe(b); }); document.fonts?.ready.then(measure); return () => ob.disconnect(); }, [current, items]);
    useEffect(() => { if (activation === 'automatic')
        setFocusId(current); }, [current, activation]);
    function key(e, index) { const enabled = items.map((x, i) => !x.disabled ? i : -1).filter(i => i >= 0); const pos = enabled.indexOf(index); let next; const rtl = getComputedStyle(e.currentTarget).direction === 'rtl'; const forward = vertical ? 'ArrowDown' : rtl ? 'ArrowLeft' : 'ArrowRight', back = vertical ? 'ArrowUp' : rtl ? 'ArrowRight' : 'ArrowLeft'; if (e.key === forward)
        next = enabled[(pos + 1) % enabled.length];
    else if (e.key === back)
        next = enabled[(pos - 1 + enabled.length) % enabled.length];
    else if (e.key === 'Home')
        next = enabled[0];
    else if (e.key === 'End')
        next = enabled[enabled.length - 1];
    else
        return; e.preventDefault(); const id = items[next].id; setFocusId(id); if (activation === 'automatic')
